/**
 * FILE: concept_6_market_timing_alarm_clock.js
 * THEME: Finance & Investment — Time Value of Money & Market Timing Alarm Clock
 * STYLE: Modern Flat Vector with Solid Chroma Green Screen (#00FF00)
 * ASPECT RATIO: 16:9 | RESOLUTION READY: FHD / 2K / 4K (Ultra HD)
 * DURATION: 20 Seconds Seamless Loop | SCENES: 1
 * TARGET EXPORT BITRATE: 100 Mbps (Uncompressed Crisp Vector Edges, Zero Glow/Bloom)
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const s = minSide / 1080;
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Fundamental harmonic phases for 100% seamless 20-second loop
  const tau = Math.PI * 2;
  const p1 = sceneProgress * tau + currentScene * 0;
  const p2 = sceneProgress * tau * 2;
  const p3 = sceneProgress * tau * 3;
  const p4 = sceneProgress * tau * 4;
  const p12 = sceneProgress * tau * 12;

  // Controlled ringing envelope (smoothly rises and settles twice during the 20s loop)
  const ringEnv = Math.pow(0.5 - 0.5 * Math.cos(p2), 2);
  const bellShake = Math.sin(p12) * ringEnv;

  // Color Palette (Crisp Commercial Flat Vector, Zero Glow)
  const COL = {
    greenScreen: '#00FF00',
    outline: '#162035',
    surfaceWhite: '#FFFFFF',
    surfaceLight: '#F1F5F9',
    surfaceMuted: '#CBD5E1',
    slateDark: '#334155',
    slateMid: '#64748B',
    goldLight: '#FEF08A',
    goldMid: '#FACC15',
    goldDark: '#EAB308',
    goldDeep: '#CA8A04',
    orangeLight: '#FED7AA',
    orangeMid: '#FB923C',
    orangeDark: '#EA580C',
    emeraldLight: '#A7F3D0',
    emeraldMid: '#22C55E',
    emeraldDark: '#15803D',
    cyanLight: '#BAE6FD',
    cyanMid: '#38BDF8',
    cyanDark: '#0284C7',
    purpleLight: '#DDD6FE',
    purpleMid: '#A855F7',
    coralRed: '#F87171'
  };

  const strokeW = 5.5 * s;
  const thinStrokeW = 3.5 * s;

  ctx.save();
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // 1. SOLID GREEN SCREEN BACKGROUND
  ctx.fillStyle = COL.greenScreen;
  ctx.fillRect(0, 0, width, height);

  // Helper: Rounded Rectangle Path
  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function fillAndStroke(fillColor, outlineColor, lineWidth) {
    if (fillColor) {
      ctx.fillStyle = fillColor;
      ctx.fill();
    }
    if (outlineColor && lineWidth > 0) {
      ctx.strokeStyle = outlineColor;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }

  // Helper: Crisp Vector Dollar Emblem
  function drawVectorDollar(centerX, centerY, scaleSize, color, lineW) {
    const w = 13 * scaleSize;
    const h = 20 * scaleSize;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    ctx.moveTo(centerX + w * 0.75, centerY - h * 0.45);
    ctx.bezierCurveTo(
      centerX + w * 0.75, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.35
    );
    ctx.bezierCurveTo(
      centerX - w * 0.85, centerY + h * 0.02,
      centerX + w * 0.85, centerY - h * 0.02,
      centerX + w * 0.85, centerY + h * 0.40
    );
    ctx.bezierCurveTo(
      centerX + w * 0.85, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.45
    );
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(centerX, centerY - h * 0.98);
    ctx.lineTo(centerX, centerY + h * 0.98);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Vector Upward Arrow
  function drawUpArrow(centerX, centerY, size, color, lineW) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + size * 0.7);
    ctx.lineTo(centerX, centerY - size * 0.65);
    ctx.moveTo(centerX - size * 0.55, centerY - size * 0.1);
    ctx.lineTo(centerX, centerY - size * 0.7);
    ctx.lineTo(centerX + size * 0.55, centerY - size * 0.1);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Gold Coin Medallion
  function drawGoldMedallion(centerX, centerY, radius, dollarScale) {
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, 0, tau);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.arc(centerX, centerY, radius * 0.74, 0, tau);
    fillAndStroke(COL.goldLight, COL.outline, 2.5 * s);

    drawVectorDollar(centerX, centerY, dollarScale, COL.outline, 3.2 * s);
  }

  // Helper: Side-View Stacked Coin Cylinder
  function drawCoinCylinder(centerX, topY, coinW, coinH) {
    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    roundedRectPath(centerX - coinW * 0.40, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldLight, null, 0);

    roundedRectPath(centerX + coinW * 0.20, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldDeep, null, 0);

    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(null, COL.outline, thinStrokeW);
  }

  // =========================================================================
  // 2. STRUCTURAL BASELINE PLATFORM & NON-INTERSECTING TIMING BRIDGES
  // =========================================================================
  const baseLineY = cy + 395 * s;

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = strokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 735 * s, baseLineY);
  ctx.lineTo(cx + 735 * s, baseLineY);
  ctx.stroke();

  // Outer baseline accent ticks
  const tickShift = Math.sin(p2) * 6 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 810 * s - tickShift, baseLineY);
  ctx.lineTo(cx - 760 * s - tickShift, baseLineY);
  ctx.moveTo(cx + 760 * s + tickShift, baseLineY);
  ctx.lineTo(cx + 810 * s + tickShift, baseLineY);
  ctx.stroke();

  // Sub-platform line
  ctx.beginPath();
  ctx.moveTo(cx - 360 * s, baseLineY + 18 * s);
  ctx.lineTo(cx + 360 * s, baseLineY + 18 * s);
  ctx.stroke();

  // Dedicated Horizontal Timing Bridges in Lower Corridor (y = cy + 205*s)
  // Left gap: [cx - 285*s, cx - 220*s] | Right gap: [cx + 220*s, cx + 285*s]
  const bridgeY = cy + 205 * s;
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = thinStrokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 280 * s, bridgeY);
  ctx.lineTo(cx - 222 * s, bridgeY);
  ctx.moveTo(cx + 222 * s, bridgeY);
  ctx.lineTo(cx + 280 * s, bridgeY);
  ctx.stroke();

  const bProgL = (sceneProgress * 4) % 1;
  ctx.beginPath();
  ctx.arc(cx - 274 * s + bProgL * 46 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.cyanMid, COL.outline, 2.5 * s);

  const bProgR = (sceneProgress * 4 + 0.5) % 1;
  ctx.beginPath();
  ctx.arc(cx + 228 * s + bProgR * 46 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, 2.5 * s);

  // =========================================================================
  // 3. LEFT-TOP ZONE: DIVIDEND SCHEDULE & MARKET CYCLE CALENDAR CARD
  // Bounding Box: x in [cx - 685*s, cx - 295*s], y in [cy - 360*s, cy - 35*s]
  // =========================================================================
  const ltFloatY = Math.sin(p2) * 4.5 * s;
  const ltX = cx - 685 * s;
  const ltY = cy - 360 * s + ltFloatY;
  const ltW = 390 * s;
  const ltH = 315 * s;

  roundedRectPath(ltX, ltY, ltW, ltH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Top Calendar Header Banner
  roundedRectPath(ltX + 16 * s, ltY + 18 * s, ltW - 32 * s, 52 * s, 12 * s);
  fillAndStroke(COL.cyanMid, COL.outline, thinStrokeW);

  // 4 Calendar Binder Rings along Top Header (Strictly inside ltY + 8*s to ltY + 32*s)
  for (let r = 0; r < 4; r++) {
    const rx = ltX + 68 * s + r * 84 * s;
    roundedRectPath(rx - 7 * s, ltY + 8 * s, 14 * s, 24 * s, 5 * s);
    fillAndStroke(COL.surfaceWhite, COL.outline, 2.8 * s);
  }

  // Header Title Bar & Active Cycle Pill
  roundedRectPath(ltX + 36 * s, ltY + 42 * s, 165 * s, 12 * s, 6 * s);
  fillAndStroke(COL.outline, null, 0);

  roundedRectPath(ltX + ltW - 106 * s, ltY + 34 * s, 72 * s, 24 * s, 8 * s);
  fillAndStroke(COL.goldMid, COL.outline, 2.5 * s);

  // 4 x 3 Grid of Non-Overlapping Market Timing Date Cells (y: ltY + 88*s to ltY + 292*s)
  const cols = 4;
  const rows = 3;
  const cellW = 74 * s;
  const cellH = 54 * s;
  const cellGapX = 16 * s;
  const cellGapY = 16 * s;
  const gridStartX = ltX + 23 * s;
  const gridStartY = ltY + 88 * s;

  const activeCycleCell = Math.floor(sceneProgress * 12) % 12;

  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const idx = row * cols + col;
      const cxCell = gridStartX + col * (cellW + cellGapX);
      const cyCell = gridStartY + row * (cellH + cellGapY);

      const isCurrent = idx === activeCycleCell;
      const isDividendDay = idx === 2 || idx === 7 || idx === 10;
      const cellFill = isCurrent ? COL.goldMid : (isDividendDay ? COL.emeraldLight : COL.surfaceLight);

      roundedRectPath(cxCell, cyCell, cellW, cellH, 10 * s);
      fillAndStroke(cellFill, COL.outline, 2.8 * s);

      // Top mini bar inside cell
      roundedRectPath(cxCell + 14 * s, cyCell + 14 * s, 28 * s, 8 * s, 4 * s);
      fillAndStroke(COL.slateMid, null, 0);

      // Bottom status dot or bar inside cell
      if (isCurrent || isDividendDay) {
        ctx.beginPath();
        ctx.arc(cxCell + cellW - 20 * s, cyCell + cellH - 18 * s, 7 * s, 0, tau);
        fillAndStroke(isCurrent ? COL.orangeMid : COL.emeraldMid, COL.outline, 2.2 * s);
      } else {
        roundedRectPath(cxCell + 14 * s, cyCell + 32 * s, cellW - 28 * s, 8 * s, 4 * s);
        fillAndStroke(COL.surfaceMuted, null, 0);
      }
    }
  }

  // =========================================================================
  // 4. LEFT-BOTTOM ZONE: ASSET HORIZON ALLOCATION & GOLD RESERVES PEDESTAL
  // Bounding Box: x in [cx - 685*s, cx - 295*s], y in [cy + 25*s, cy + 395*s]
  // =========================================================================
  const lbFloatY = Math.cos(p2) * 4 * s;
  const lbX = cx - 685 * s;
  const lbY = cy + 25 * s + lbFloatY;
  const lbW = 390 * s;
  const lbCardH = 190 * s;

  // 4A. Upper Time-Horizon Allocation Card
  roundedRectPath(lbX, lbY, lbW, lbCardH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Left Segmented Donut Ring inside Card
  const dCX = lbX + 80 * s;
  const dCY = lbY + lbCardH * 0.5;
  const dR = 52 * s;
  const dAngles = [0, tau * 0.40, tau * 0.75, tau];
  const dCols = [COL.goldMid, COL.cyanMid, COL.emeraldMid];

  for (let k = 0; k < 3; k++) {
    ctx.beginPath();
    ctx.moveTo(dCX, dCY);
    ctx.arc(dCX, dCY, dR, p1 + dAngles[k], p1 + dAngles[k + 1]);
    ctx.closePath();
    fillAndStroke(dCols[k], COL.outline, thinStrokeW);
  }
  ctx.beginPath();
  ctx.arc(dCX, dCY, 24 * s, 0, tau);
  fillAndStroke(COL.surfaceWhite, COL.outline, thinStrokeW);

  // Right 3 Horizon Progress Meters
  const mStartX = lbX + 156 * s;
  const mWidth = 210 * s;
  for (let m = 0; m < 3; m++) {
    const my = lbY + 34 * s + m * 48 * s;
    roundedRectPath(mStartX, my, 84 * s, 9 * s, 4.5 * s);
    fillAndStroke(COL.slateMid, null, 0);

    roundedRectPath(mStartX, my + 15 * s, mWidth, 18 * s, 9 * s);
    fillAndStroke(COL.surfaceLight, COL.outline, 2.5 * s);

    const mFill = (0.55 + 0.28 * Math.sin(p2 + m * 1.15)) * (mWidth - 6 * s);
    roundedRectPath(mStartX + 3 * s, my + 18 * s, mFill, 12 * s, 6 * s);
    fillAndStroke(dCols[m], null, 0);
  }

  // 4B. Lower Gold Bullion & Coin Pedestal on baseLineY
  const pedLX = lbX;
  const pedLW = lbW;
  const pedLH = 24 * s;
  const pedLY = baseLineY - pedLH;

  roundedRectPath(pedLX, pedLY, pedLW, pedLH, 8 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  function drawBullionBar(centerX, bottomY, barW, barH) {
    const topW = barW * 0.78;
    ctx.beginPath();
    ctx.moveTo(centerX - barW * 0.5, bottomY);
    ctx.lineTo(centerX - topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + barW * 0.5, bottomY);
    ctx.closePath();
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.moveTo(centerX - topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.42, bottomY - 7 * s);
    ctx.lineTo(centerX - topW * 0.42, bottomY - 7 * s);
    ctx.closePath();
    fillAndStroke(COL.goldLight, null, 0);
  }

  // Column 1 (Left): 2 Stacked Gold Bullion Bars (x center = lbX + 84*s, spans [22, 146])
  const bulCX = lbX + 84 * s;
  drawBullionBar(bulCX, pedLY, 124 * s, 38 * s);
  drawBullionBar(bulCX, pedLY - 38 * s, 108 * s, 36 * s);

  // Column 2 (Middle): 4 Stacked Gold Coins (x center = lbX + 216*s, spans [174, 258], 28*s clear gap!)
  const stackLCX = lbX + 216 * s;
  const cH = 24 * s;
  for (let c = 0; c < 4; c++) {
    drawCoinCylinder(stackLCX, pedLY - (c + 1) * cH, 84 * s, cH);
  }

  // Column 3 (Right): Front Gold Dollar Medallion on Stand (x center = lbX + 330*s, spans [286, 374], 28*s clear gap!)
  const medLCX = lbX + 330 * s;
  const medLCY = pedLY - 64 * s + Math.sin(p2) * 4 * s;
  roundedRectPath(medLCX - 22 * s, pedLY - 16 * s, 44 * s, 16 * s, 5 * s);
  fillAndStroke(COL.goldDeep, COL.outline, thinStrokeW);
  drawGoldMedallion(medLCX, medLCY, 44 * s, 1.25 * s);

  // =========================================================================
  // 5. CENTER ZONE: MARKET TIMING ALARM CLOCK HUB
  // Directly inspired by the yellow/orange twin-bell alarm clock in reference video (00:25 - 00:31)
  // Clock Center: (cx, cy + 45*s + clockFloatY), Outer Radius: 185*s
  // =========================================================================
  const clockFloatY = Math.sin(p2) * 4.5 * s;
  const clockTilt = bellShake * 0.022;
  const clockCX = cx;
  const clockCY = cy + 42 * s + clockFloatY;
  const outerClockR = 184 * s;
  const midRingR = 154 * s;
  const faceR = 132 * s;

  // 5A. Central Clock Pedestal Platform on baseLineY (y: cy + 357*s to cy + 395*s)
  const cPedW = 310 * s;
  const cPedH = 38 * s;
  const cPedX = cx - cPedW * 0.5;
  const cPedY = baseLineY - cPedH;

  roundedRectPath(cPedX, cPedY, cPedW, cPedH, 12 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  roundedRectPath(cPedX + 42 * s, cPedY + 14 * s, cPedW - 84 * s, 10 * s, 5 * s);
  fillAndStroke(COL.goldMid, null, 0);

  ctx.save();
  ctx.translate(clockCX, clockCY);
  ctx.rotate(clockTilt);

  // 5B. Two Angled Alarm Clock Legs (Extending from bottom of clock casing to pedestal)
  const legAngles = [Math.PI * 0.5 + 0.52, Math.PI * 0.5 - 0.52];
  for (let lg = 0; lg < 2; lg++) {
    const la = legAngles[lg];
    const x1 = Math.cos(la) * (outerClockR - 12 * s);
    const y1 = Math.sin(la) * (outerClockR - 12 * s);
    const x2 = Math.cos(la) * (outerClockR + 48 * s);
    const y2 = Math.sin(la) * (outerClockR + 48 * s);

    ctx.strokeStyle = COL.outline;
    ctx.lineWidth = 22 * s;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();

    ctx.strokeStyle = COL.orangeMid;
    ctx.lineWidth = 11 * s;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
  }

  // 5C. Twin Bell Domes & Central Striker Hammer (Top-Left at -50 deg, Top-Right at +50 deg)
  const bellAngles = [-Math.PI * 0.5 - 0.74, -Math.PI * 0.5 + 0.74];
  const bellDist = outerClockR + 38 * s;
  const bellDomeR = 68 * s;

  for (let b = 0; b < 2; b++) {
    const ba = bellAngles[b];
    // Strut post connecting clock casing to bell dome
    const sx1 = Math.cos(ba) * (outerClockR - 6 * s);
    const sy1 = Math.sin(ba) * (outerClockR - 6 * s);
    const sx2 = Math.cos(ba) * (bellDist - 6 * s);
    const sy2 = Math.sin(ba) * (bellDist - 6 * s);

    ctx.strokeStyle = COL.outline;
    ctx.lineWidth = 14 * s;
    ctx.beginPath();
    ctx.moveTo(sx1, sy1);
    ctx.lineTo(sx2, sy2);
    ctx.stroke();

    // Bell Dome (Rotated cleanly to face outward along ba)
    const bx = Math.cos(ba) * bellDist;
    const by = Math.sin(ba) * bellDist;
    const individualBellRot = ba + Math.PI * 0.5 + bellShake * 0.06 * (b === 0 ? -1 : 1);

    ctx.save();
    ctx.translate(bx, by);
    ctx.rotate(individualBellRot);

    // Semi-circular bell dome
    ctx.beginPath();
    ctx.arc(0, 0, bellDomeR, Math.PI, 0, false);
    ctx.closePath();
    fillAndStroke(COL.goldMid, COL.outline, strokeW);

    // Inner orange-gold shading band on right side of dome
    ctx.save();
    ctx.clip();
    ctx.fillStyle = COL.orangeMid;
    ctx.fillRect(10 * s, -bellDomeR, bellDomeR, bellDomeR);
    ctx.restore();

    // Re-stroke Bell Dome outline
    ctx.beginPath();
    ctx.arc(0, 0, bellDomeR, Math.PI, 0, false);
    ctx.closePath();
    fillAndStroke(null, COL.outline, strokeW);

    // Top button nub on Bell Dome
    ctx.beginPath();
    ctx.arc(0, -bellDomeR - 6 * s, 9 * s, 0, tau);
    fillAndStroke(COL.orangeDark, COL.outline, thinStrokeW);

    // 2 Crisp Sound Wave Arcs outside each Bell Dome (Strictly within safe clearance)
    const waveAlpha = 0.35 + 0.65 * ringEnv;
    ctx.save();
    ctx.globalAlpha = waveAlpha;
    ctx.strokeStyle = COL.outline;
    ctx.lineWidth = 4 * s;
    for (let w = 0; w < 2; w++) {
      const wr = bellDomeR + (22 + w * 16 + ringEnv * 4) * s;
      ctx.beginPath();
      ctx.arc(0, 0, wr, -Math.PI * 0.72, -Math.PI * 0.28, false);
      ctx.stroke();
    }
    ctx.restore();

    ctx.restore();
  }

  // Central Striker Hammer at Top Apex (0, -outerClockR)
  const hammerPivotY = -outerClockR + 2 * s;
  const hammerRot = bellShake * 0.16;
  ctx.save();
  ctx.translate(0, hammerPivotY);
  ctx.rotate(hammerRot);

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 10 * s;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(0, -34 * s);
  ctx.stroke();

  roundedRectPath(-24 * s, -52 * s, 48 * s, 20 * s, 9 * s);
  fillAndStroke(COL.orangeMid, COL.outline, strokeW);
  ctx.restore();

  // 5D. Outer Clock Casing, White Contrast Ring & Inner Portfolio Pie Chart Face
  // Outer Gold-Orange Bezel
  ctx.beginPath();
  ctx.arc(0, 0, outerClockR, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, strokeW);

  // Inner White Contrast Ring (Matches reference video concentric black/white rings)
  ctx.beginPath();
  ctx.arc(0, 0, midRingR, 0, tau);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Inner Clock Face with 4 Portfolio Asset Allocation Sectors (Warm Gold/Amber/Emerald/Cyan)
  const sectorAngles = [-Math.PI * 0.5, 0.15, Math.PI * 0.65, Math.PI * 1.15, Math.PI * 1.5];
  const sectorColors = [COL.goldMid, COL.orangeMid, COL.goldLight, COL.emeraldLight];

  for (let sc = 0; sc < 4; sc++) {
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.arc(0, 0, faceR, sectorAngles[sc], sectorAngles[sc + 1], false);
    ctx.closePath();
    fillAndStroke(sectorColors[sc], COL.outline, thinStrokeW);
  }

  // Inner Circular Face Track (Leaves clean outer margin for the 12 hour ticks)
  ctx.beginPath();
  ctx.arc(0, 0, faceR * 0.72, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

  // 12 Crisp Hour Tick Marks around Clock Face Perimeter
  for (let h = 0; h < 12; h++) {
    const ha = (h * tau) / 12 - Math.PI * 0.5;
    const isMajor = h % 3 === 0;
    const rOuter = faceR - 8 * s;
    const rInner = faceR - (isMajor ? 24 : 16) * s;

    ctx.strokeStyle = COL.outline;
    ctx.lineWidth = (isMajor ? 5 : 3.5) * s;
    ctx.beginPath();
    ctx.moveTo(Math.cos(ha) * rInner, Math.sin(ha) * rInner);
    ctx.lineTo(Math.cos(ha) * rOuter, Math.sin(ha) * rOuter);
    ctx.stroke();
  }

